interface CountryOption {
  disabled?: boolean
  label: string
  value: string
}

type Country = CountryOption | string

interface Props extends Omit<HTMLAttributes<'div'>, 'size'> {
  class?: string | null
  className?: string
  countries?: Country[]
  countryLabel?: string
  countryName?: string
  countryValue?: string
  name?: string
  placeholder?: string
  size?: 'default' | 'lg' | 'sm'
  value?: string
}

const {
  class: classProp = '',
  className = '',
  countries = [],
  countryLabel = 'Country code',
  countryName = 'country',
  countryValue,
  name = 'phone',
  placeholder = 'Phone number',
  size = 'default',
  value,
  ...rest
} = Astro.props

const normalizedCountries = countries.map(country => typeof country === 'string' ? { label: country, value: country } : country)
const hasCountryValue = countryValue !== undefined

const { classList, passthrough } = resolveLumenAstroProps(rest, [
  'ui-phone-input',
  'ui-input-group'
], classProp, className)
