    name={countryName}
  >
    {normalizedCountries.map(country => (
      <option
        disabled={country.disabled}
        selected={hasCountryValue && country.value === countryValue}
        value={country.value}
      >{country.label}
      </option>
    ))}
  </select>
  <input
    autocomplete="tel"
    class:list={[
      'ui-input',
      'ui-phone-input__number',
      size === 'sm' && 'ui-input--sm',
      size === 'lg' && 'ui-input--lg'
