  ComponentPropsWithoutRef<'div'>,
  'defaultValue'
> {
  countries?: SelectOption[]
  countryLabel?: string
  countryName?: string
  defaultCountryValue?: string
  defaultValue?: string
  name?: string
  placeholder?: string
  size?: 'default' | 'lg' | 'sm'
}

export const PhoneInput = ({
  className,
  countries = emptyOptions,
  countryLabel = 'Country code',
  countryName = 'country',
  defaultCountryValue,
  defaultValue,
  name = 'phone',
  placeholder = 'Phone number',
  size = 'default',
  ...props
}: PhoneInputProps) => {
  const { selectClass, inputClass } = phoneInputSizeModifiers(size)

  return (
    <div
      className={composeClassName('ui-phone-input ui-input-group', className)}
      {...props}
    >
      <select
        aria-label={countryLabel}
        className={composeClassName(
          'ui-select ui-phone-input__country', selectClass
        )}
        defaultValue={defaultCountryValue}
        name={countryName}
      >
        {countries.map(normalizeOption).map(option => (
          <option
            disabled={option.disabled}
            key={option.value}
            value={option.value}
          >
            {option.label}
          </option>
        ))}
      </select>
      <input
        autoComplete="tel"
        className={composeClassName(
          'ui-input ui-phone-input__number', inputClass
        )}
        defaultValue={defaultValue}
        inputMode="tel"
        name={name}
        placeholder={placeholder}
        type="tel"
      />
    </div>
  )
}

