  items = emptyDescriptionsItems,
  style,
  ...props
}: DescriptionsProps) => (
  <dl
    className={composeClassName('ui-descriptions', className)}
    data-columns={columns}
    style={{ ['--ui-descriptions-columns' as string]: columns, ...style }}
    {...props}
